const date = new Date("2026-05-17");

// Add 7 days to date

date.setDate(date.getDate() + 7);

// Here the original date is lost

// Create a Date

const date1 = new Date("2026-05-17");

// Create a copy

const date2 = date1;

// Add 7 days to date1

date1.setDate(date1.getDate() + 7);

